import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/yfr4')
from lib import *
FVG="Portions de fruits et légumes"
def fv(n): return f"{FVG}§{FVG} par portion : {n}"
FRZ="Instructions de congélation : "
recs=[
R(7816882,"Églefin sauce verte, brocoli et purée de haricots","Un églefin au léger parfum de citron, servi dans une salsa débordante d'herbes et de légumes verts.","2","407 g",
["2 gros filets d'églefin frais avec la peau","Spray d'huile d'olive 1 calorie","1 boîte de 400 g de haricots borlotti, égouttés","300 g de bouquets de brocoli","1 poignée chacun de persil plat, de basilic et de menthe","1 gousse d'ail, écrasée","2 c. à soupe d'huile d'olive","2 petits cornichons, émincés","3 filets d'anchois","2 c. à soupe de crème fraîche allégée"],
["Vaporisez une pression d'huile sur l'églefin et posez-le, côté peau vers le haut, sur une feuille de papier sulfurisé. Préchauffez le gril à puissance maximale et faites griller le poisson 3 à 4 minutes. Retournez, vaporisez d'huile et faites griller encore 3 à 4 minutes. Pendant ce temps, portez à ébullition une grande casserole d'eau, ajoutez les haricots et le brocoli et laissez mijoter 5 minutes.","Mettez les herbes, l'ail, l'huile et les cornichons dans un blender. Rincez les filets d'anchois pour enlever le sel et séchez-les. Ajoutez-les dans le blender et mixez la sauce jusqu'à ce qu'elle soit finement hachée, en ajoutant 1 c. à café d'eau pour l'éclaircir si nécessaire. Égouttez le brocoli et les haricots, remettez-les dans la casserole, ajoutez la crème fraîche et écrasez grossièrement. Répartissez la purée dans 2 assiettes, déposez dessus le poisson et ajoutez la sauce verte. Servez avec un quartier de citron."],
[fv(3)]),
R(7817889,"Pizza aux légumes rôtis","Cette superbe pizza sans gluten est une excellente idée, que vous soyez cœliaque ou non.","4","305 g",
["75 g de pommes de terre, épluchées et coupées en petits morceaux","50 g de farine de pois chiches","125 g de riz moulu","50 g de fécule de maïs","½ c. à café de bicarbonate de soude","½ c. à café de crème de tartre","25 g de matière grasse tartinable au tournesol","125 ml de lait demi-écrémé","un peu d'huile pour graisser","Pour la garniture§4 tomates moyennes, coupées en tranches","Pour la garniture§½ poivron rouge, émincé","Pour la garniture§½ poivron jaune, émincé","Pour la garniture§1 petit oignon rouge, émincé","Pour la garniture§1 petite boîte (290 g) de champignons de Paris, égouttés et coupés en deux","Pour la garniture§40 g de feta, émiettée","Pour la garniture§1 poignée de feuilles de basilic frais, déchirées"],
["Plongez les pommes de terre dans une casserole d'eau bouillante et faites-les cuire 15 minutes, jusqu'à ce qu'elles soient tendres, puis écrasez-les.","Préchauffez le four à 220 °C (th. 7). Dans un grand saladier, mélangez la farine de pois chiches, le riz moulu, la fécule de maïs, le bicarbonate de soude et la crème de tartre.","Incorporez du bout des doigts la pomme de terre et la matière grasse jusqu'à ce que le mélange ressemble à de la chapelure.","Ajoutez juste assez de lait pour obtenir une pâte souple, formez une boule, puis étalez-la en un disque de 30 cm et posez-le sur une plaque de cuisson légèrement huilée.","Garnissez de tranches de tomate, de poivrons et d'oignon, et de moitiés de champignons.","Émiettez la feta dessus et faites cuire 15 à 20 minutes, jusqu'à ce que les légumes soient tendres et que la pâte soit dorée et croustillante.","Parsemez de basilic et servez."],
["Pour une croûte à l'ail, ajoutez simplement 2 à 3 gousses d'ail écrasées aux pommes de terre.","Pour plus de saveur, saupoudrez 1 c. à café d'origan séché et une pincée de flocons de piment sur les tranches de tomate avant d'ajouter les poivrons et l'oignon.",fv(3)]),
R(7822207,"Tortillas garnies de poulet et de salade","Vous pouvez préparer ce déjeuner sain et rassasiant en 30 minutes seulement.","2","469 g",
["1 c. à café d'huile d'olive","1 petit oignon, haché","1 poivron rouge, émincé","1 blanc de poulet sans os ni peau, émincé (150 g)","1 boîte de 400 g de haricots rouges, égouttés et rincés","1 c. à soupe de crème fraîche allégée","2 petites tortillas de blé","1 carotte, épluchée et râpée","60 g de salade mélangée","poivre noir fraîchement moulu"],
["Chauffez l'huile dans une poêle antiadhésive. Ajoutez l'oignon et le poivron rouge et faites revenir 2 à 3 minutes, jusqu'à ce qu'ils soient ramollis. Ajoutez le poulet et faites revenir 3 à 4 minutes, jusqu'à ce qu'il soit doré et cuit à cœur.","Pendant ce temps, écrasez ensemble les haricots rouges et la crème fraîche dans un bol. Réchauffez les tortillas.","Répartissez le mélange de haricots sur les tortillas et déposez dessus le mélange de poulet. Ajoutez la carotte et la salade, poivrez bien, roulez et servez."],
["Vous pouvez utiliser des escalopes de dinde émincées à la place du poulet.","Pour une version végétarienne, remplacez le poulet par 200 g de champignons émincés.","Les tortillas se congèlent bien : vous pouvez donc congeler le paquet et en utiliser au fur et à mesure.",fv(3)]),
R(7823636,"Brownies au chocolat","Ces brownies moelleux sont parfaits pour une gourmandise occasionnelle.","12","62 g",
["100 g de chocolat noir, cassé en morceaux","25 g de matière grasse végétale tartinable allégée","250 g de betteraves cuites (à l'eau)","1 c. à café de café soluble en granulés, dissous dans 1 c. à café d'eau","2 œufs moyens, battus","½ c. à café d'extrait de vanille","2 c. à soupe de sirop d'érable","100 g d'amandes en poudre","50 g de farine complète ordinaire","50 g de cacao en poudre","10 c. à café d'édulcorant artificiel en poudre","½ c. à café de levure chimique"],
["Préchauffez le four à 180 °C (th. 4). Graissez un moule de 20 x 20 cm et chemisez-le de papier sulfurisé.","Faites fondre le chocolat et la matière grasse allégée dans un bol placé au-dessus d'une casserole d'eau frémissante, ou au micro-ondes, en remuant souvent. Laissez refroidir un peu.","Épongez l'excès de liquide de la betterave avec du papier absorbant. Mettez-la dans un blender avec le café dissous, les œufs, l'extrait de vanille et le sirop d'érable. Mixez jusqu'à obtenir une purée.","Ajoutez les amandes en poudre, la farine, le cacao, l'édulcorant et la levure et mixez jusqu'à ce que le tout soit bien mélangé.","Versez la préparation dans le moule préparé et lissez le dessus avec une cuillère. Faites cuire au four 15 à 20 minutes, ou jusqu'à ce que le dessus soit ferme et qu'une brochette plantée au centre du brownie ressorte avec quelques miettes collantes, mais sans pâte liquide.","Laissez refroidir 15 minutes, coupez en carrés ou en rectangles et servez."],
["Vous pouvez préparer des brownies aux fruits en ajoutant 2 c. à soupe de raisins secs, ou essayez 2 c. à soupe de noix hachées ou d'amandes effilées.",FRZ+"peut être congelé une fois cuit. Congelez en portions emballées individuellement. Décongelez 2 heures au réfrigérateur ou au micro-ondes en position basse/décongélation."]),
R(7832382,"Sauce tomate","Une sauce tomate de base, facile à préparer, parfaite pour les pâtes comme pour les pizzas.","4","126 g",
["2 c. à café d'huile d'olive","1 oignon, finement haché","2 gousses d'ail, émincées","1 boîte de 400 g de tomates","1 c. à soupe de concentré de tomate","1 c. à café bombée d'origan séché","1 bonne pincée de poivre noir","5 à 6 feuilles de basilic frais"],
["Chauffez l'huile dans une casserole, ajoutez l'oignon et faites cuire 2 minutes, jusqu'à ce qu'il commence à dorer, puis ajoutez l'ail et faites cuire encore 1 à 2 minutes.","Ajoutez tous les autres ingrédients et laissez mijoter doucement 5 minutes.","Mixez jusqu'à obtenir une texture lisse et servez."],
["Pour épaissir la sauce pour une pizza, laissez-la simplement mijoter doucement 5 à 10 minutes de plus en remuant régulièrement, afin de faire évaporer davantage de liquide.","Pour faire manger plus de légumes aux enfants difficiles, ajoutez un poivron rouge finement haché avec les oignons.","Transformez-la en sauce puttanesca en ajoutant une bonne pincée de flocons de piment, des olives noires et quelques câpres.","Congelez dans des gobelets en plastique, puis enveloppez dans des sacs de congélation une fois congelée.",fv(1)]),
R(7832746,"Bircher muesli pommes et canneberges","Un petit-déjeuner rassasiant et fruité pour bien démarrer la journée.","4","230 g",
["120 g de flocons d'avoine","150 g de yaourt nature sans matières grasses","3 pommes, épluchées, évidées et râpées","1 c. à soupe de graines de tournesol","1 c. à soupe de graines de courge","40 g de canneberges séchées","3 c. à café de graines de chia et 1 pomme, évidée et coupée en dés, pour servir"],
["Préparez le muesli la veille au soir. Mettez les flocons d'avoine dans un récipient à couvercle. Ajoutez le yaourt, la pomme râpée, les graines de tournesol et de courge, les canneberges séchées et 150 ml d'eau. Mélangez bien. Couvrez et réfrigérez toute la nuit.","Le lendemain matin, remuez bien le muesli. S'il est trop épais, ajoutez un peu d'eau jusqu'à obtenir la consistance souhaitée.","Incorporez 2 c. à café de graines de chia à votre muesli, puis répartissez dans des bols. Parsemez du reste des graines de chia et de la pomme coupée en dés, puis servez."],
["Vous pouvez utiliser toute combinaison de fruits et de graines dans cette recette. Essayez par exemple des framboises, des bananes, des graines de chia ou de lin."]),
R(7833036,"Papillotes de fruits de mer","Saumon, crevettes et lieu noir avec brocoli, oignons nouveaux et poivrons, le tout cuit ensemble dans une papillote en aluminium.","2","307 g",
["160 g de bouquets de brocoli","100 g de saumon, coupé en cubes","100 g de lieu noir, coupé en 2 morceaux","50 g de crevettes","6 oignons nouveaux, émincés","1 poivron rouge, coupé en lanières","10 g de persil","poivre noir","jus de citron, plus 2 quartiers pour servir","2 c. à soupe d'eau","2 c. à café d'huile d'olive"],
["Préchauffez le four à 180 °C (th. 5). Blanchissez le brocoli 3 à 4 minutes dans de l'eau bouillante et égouttez.","Répartissez à parts égales le poisson, les fruits de mer et les légumes sur 2 grands carrés de papier aluminium de 25 cm x 25 cm.","Parsemez de persil et poivrez généreusement. Pressez du citron sur chaque papillote, puis ajoutez l'eau et l'huile d'olive.","Rabattez le papier aluminium vers le centre pour former une papillote, puis placez sur une plaque de cuisson et faites cuire 15 minutes.","Servez chaque papillote avec un quartier de citron."],
["Ce plat fonctionne avec n'importe quel poisson blanc. Vous pouvez aussi n'utiliser que du saumon, ou omettre les crevettes.",fv(2)]),
R(7833058,"Salade de maquereau mariné","Un plat léger et sain, parfait pour manger en plein air. Merci à la célèbre cheffe Sophie Grigson pour cette recette.","8","100 g",
["4 filets de maquereau fumé (70 g chacun)","jus d'1 citron","2 c. à café de sucre en poudre","10 baies de genièvre, grossièrement écrasées","Pour la salade§2 pains pita complets","Pour la salade§120 g de roquette","Pour la salade§200 g de tomates cerises, coupées en deux","Pour la salade§2 c. à soupe d'huile d'olive extra vierge","Pour la salade§quartiers de citron, pour servir"],
["Préchauffez le gril à 180 °C (th. 4).","Émiettez les filets de maquereau en retirant les peaux et les arêtes éventuelles.","Mélangez avec le jus de citron, le sucre et les baies de genièvre et réservez au moins 1 heure.","Pour préparer la salade, ouvrez les pains pita en deux, faites-les griller jusqu'à ce qu'ils soient croustillants et cassez-les en morceaux. Mélangez la roquette avec les tomates cerises, le maquereau et son jus, les morceaux de pita et l'huile d'olive.","Répartissez dans 8 assiettes et servez."],
["Pour une version sans gluten, vous pouvez utiliser des pommes de terre nouvelles bouillies, coupées en tranches épaisses, à la place du pain pita.","Essayez des filets de truite fumée à la place du maquereau pour un plat plus léger et plus coloré.","Pour les végétariens, remplacez le maquereau par un quart d'avocat : il n'est pas nécessaire de le faire mariner.",fv(0)]),
R(7833905,"Tarte rustique aux fruits","Des pommes et des fruits rouges juteux dans une croûte de pâte croustillante.","4","177 g",
["150 g de pâte brisée prête à l'emploi","un peu de farine, pour étaler","2 c. à soupe de lait demi-écrémé","1 c. à soupe de semoule","2 pommes à cuire, épluchées, évidées et coupées en morceaux","100 g de mûres","1 c. à soupe de sucre demerara"],
["Préchauffez le four à 200 °C (th. 6).","Farinez le plan de travail et étalez la pâte en un disque de 25 cm de diamètre. Badigeonnez d'un peu de lait et saupoudrez de semoule.","Mélangez les pommes, les mûres et la moitié du sucre et déposez sur la pâte en laissant un espace de 6 cm sur le pourtour.","Repliez les bords de la pâte et pressez-les ensemble (le dessus de la tarte doit rester ouvert), badigeonnez du reste du lait et saupoudrez du reste du sucre.","Faites cuire 25 à 30 minutes, jusqu'à ce que la tarte soit dorée et les fruits tendres. Servez avec un peu de crème fraîche, de yaourt ou de glace."],
["Si vous aimez une tarte plus juteuse et plus tendre, faites cuire les pommes et les mûres 3 à 4 minutes dans une casserole avec 1 c. à soupe d'eau et étalez-les sur la pâte.","Vous pouvez aussi utiliser des poires, des abricots, des pêches, des nectarines ou des cerises."]),
R(7835214,"Cabillaud et légumes d'hiver rôtis","Ce repas savoureux et riche en protéines vous aidera à respecter la recommandation hebdomadaire de consommation de poisson.","2","500 g",
["1 c. à café d'huile d'olive","2 c. à café de miel liquide","zeste râpé et jus d'1 citron","300 g de courge butternut, épluchée, épépinée et coupée en morceaux","1 grosse patate douce (300 g), épluchée et coupée en morceaux","1 grosse carotte, coupée en morceaux (150 g)","1 brin de romarin, haché","2 gros morceaux de filet de cabillaud sans peau, d'environ 150 g chacun"],
["Préchauffez le four à 200 °C (th. 6).","Dans un petit bol, mélangez l'huile, le miel, le zeste et le jus de citron.","Badigeonnez tous les légumes d'un peu du mélange au miel, puis disposez-les sur une plaque de cuisson épaisse et parsemez de romarin.","Faites cuire environ 45 minutes, jusqu'à ce qu'ils commencent à caraméliser.","Placez les morceaux de cabillaud sur la plaque et poursuivez la cuisson 10 à 12 minutes. Servez enfin avec une salade verte en accompagnement, si vous le souhaitez."],
["Le saumon, l'églefin ou le thon frais conviennent bien à cette recette.","Variez en utilisant du thym à la place du romarin. Vous pouvez aussi ajouter de gros quartiers d'oignon non épluché avec le reste des légumes.",fv(4)]),
R(7836528,"Hachis parmentier végétarien, purée de carotte et de rutabaga","L'association d'une garniture généreuse de « viande hachée » végétarienne, recouverte d'une délicieuse purée de carotte et de rutabaga, donne un hachis parmentier nouveau et amélioré. Cette recette a été sélectionnée en partenariat avec Slimming World.","4","740 g",
["Spray de cuisson basses calories","1 oignon, finement haché","3 grosses branches de céleri, finement émincées","250 g de champignons de Paris, coupés en deux ou en quatre","2 gousses d'ail, écrasées","1 c. à soupe de concentré de tomate","300 g de hachis de protéines de soja/végétales surgelé nature, décongelé","1 boîte de 400 g de tomates concassées","600 ml de bouillon de légumes chaud préparé avec 1 cube de bouillon pauvre en sel","2 c. à café de Marmite, ou autre extrait de levure","2 à 3 brins de thym frais","2 petits rutabagas (environ 750 g au total), épluchés et grossièrement coupés","400 g de carottes, grossièrement coupées","2 c. à soupe de yaourt grec nature sans matières grasses et non sucré","persil plat frais, haché, pour servir"],
["Vaporisez quelques pressions de spray de cuisson basses calories dans une grande poêle profonde antiadhésive et placez-la sur feu moyen. Ajoutez l'oignon, le céleri et les champignons et faites revenir 10 minutes en remuant fréquemment, jusqu'à ce qu'ils commencent à ramollir. Ajoutez l'ail avec un filet d'eau et faites cuire 2 à 3 minutes, jusqu'à ce qu'il soit parfumé.","Ajoutez le concentré de tomate et le hachis et mélangez le tout. Incorporez les tomates, le bouillon et l'extrait de levure. Poivrez, ajoutez le thym, portez à frémissement et laissez cuire 20 minutes, jusqu'à ce que les légumes soient tendres.","Pendant ce temps, préchauffez le four à 220 °C (chaleur tournante 200 °C, th. 7). Faites bouillir les rutabagas 5 minutes, puis ajoutez les carottes et faites bouillir le tout encore 15 minutes, jusqu'à ce que les légumes soient très tendres. Égouttez, poivrez et ajoutez le yaourt. Écrasez jusqu'à obtenir une purée lisse.","Versez la garniture dans un plat allant au four de 2 litres. Recouvrez de purée et striez à la fourchette. Faites cuire au four 30 à 35 minutes, jusqu'à ce que la sauce bouillonne et que le dessus commence à dorer.","Parsemez le hachis de persil et servez avec des légumes cuits à la vapeur de votre choix, en retirant les brins de thym avant de manger."],
["Vous pouvez utiliser un yaourt nature de votre choix. Toutefois, cela modifiera les informations nutritionnelles et la texture du plat.",fv(6)]),
R(7837338,"Chili aux haricots variés","Un excellent chili végétarien qui s'adapte à toutes les légumineuses que vous avez dans votre placard.","4","398 g",
["1 c. à soupe d'huile de tournesol","1 oignon, finement haché","1 gousse d'ail, écrasée","1 poivron rouge, coupé en petits morceaux","1 poivron vert, coupé en petits morceaux","1 piment rouge, épépiné et finement haché","2 boîtes de 400 g de légumineuses variées, égouttées et rincées","1 boîte de 400 g de tomates concassées","2 c. à soupe de concentré de tomate","50 g de maïs surgelé (décongelé)","1 c. à café de cumin moulu","1 c. à café d'origan séché","poivre noir fraîchement moulu","2 c. à soupe de coriandre fraîche, hachée","200 g de riz basmati blanc, cuit selon les instructions de l'emballage"],
["Chauffez l'huile de tournesol dans une casserole moyenne, ajoutez l'oignon, l'ail, les poivrons rouge et vert et le piment, et faites revenir 3 à 4 minutes, jusqu'à ce qu'ils commencent à ramollir.","Écrasez légèrement la moitié des légumineuses avec le dos d'une fourchette. Ajoutez-les dans la casserole avec le reste des légumineuses, les tomates concassées, le concentré de tomate, le maïs, le cumin, l'origan, le sel et le poivre.","Portez à ébullition, baissez le feu et laissez mijoter 10 minutes. Incorporez la coriandre et servez avec le riz cuit."],
["Vous pouvez ajouter plus ou moins de piment, selon que vous aimez les plats plus ou moins relevés.","Pourquoi ne pas essayer des lentilles corail ou vertes, des haricots rouges ou des pois chiches.",FRZ+"(sans le riz) peut être congelé une fois cuit. Décongelez ensuite au réfrigérateur ou au micro-ondes et réchauffez jusqu'à ce que le plat soit bien chaud à cœur.",fv(3)]),
R(7840147,"Cabillaud braisé aux petits pois, oignons nouveaux et carottes","Le cabillaud dans une sauce légère et crémeuse est facile à préparer et constitue une bonne façon d'utiliser des petits pois surgelés.","2","558 g",
["200 g de petites carottes Chantenay, coupées en deux dans la longueur","1 cube de bouillon de poisson pauvre en sel","200 g de petits pois surgelés","6 oignons nouveaux, coupés en tronçons de 2 cm","15 g d'aneth frais","2 pavés de cabillaud (environ 300 g)","1 c. à café de fécule de maïs dissoute dans 1 c. à soupe d'eau","20 g de fromage frais ultra-léger","poivre noir","2 quartiers de citron"],
["Préchauffez le four à 180 °C (th. 4). Mettez les carottes dans une casserole avec le cube de bouillon et 300 ml d'eau. Portez à ébullition, baissez le feu, couvrez et laissez mijoter 5 minutes.","Versez les carottes et le bouillon dans un plat allant au four. Ajoutez les petits pois et les oignons nouveaux et parsemez de 10 g d'aneth.","Placez les pavés de cabillaud dessus, couvrez de papier aluminium et faites cuire 10 minutes.","Retirez délicatement le poisson et réservez. Ajoutez la fécule de maïs aux légumes, mélangez bien et remettez au four 1 minute.","Sortez les légumes du four et incorporez le fromage frais. Répartissez les légumes et la sauce dans deux assiettes et déposez un morceau de cabillaud sur chacune. Parsemez d'aneth frais et de poivre noir et servez avec du citron."],
["Convient bien avec de l'églefin, du saumon, de la lotte ou du lieu noir. Vous pouvez ajouter quelques crevettes.","Si vous n'avez pas de petits pois surgelés, des petits pois en conserve au naturel ou du maïs surgelé conviennent tout aussi bien pour cette recette.","Vous pouvez aussi le cuire sur la cuisinière dans une casserole avec un couvercle bien ajusté.","Pour préparer à l'avance, faites cuire les carottes dans le bouillon, laissez refroidir, assemblez le tout dans un plat allant au four, puis réfrigérez jusqu'au moment de servir. Prévoyez 5 minutes de cuisson supplémentaires si vous cuisez directement à la sortie du réfrigérateur.",fv(2)]),
R(7842764,"Biscuits de Pâques","Souvent associés au West Country, ces biscuits se mangeaient traditionnellement le dimanche de Pâques.","25","19 g",
["6 c. à soupe d'huile de colza","1 œuf","50 g de sucre roux (10 c. à café bombées)","1,5 à 2 c. à café de stévia ou d'un autre édulcorant (équivalent à 5 c. à café bombées de sucre)","zeste finement râpé d'1 citron","jus d'un demi-citron","200 g de farine complète","1 c. à café rase de mélange d'épices (mixed spice)","40 g de raisins de Corinthe","10 g de zestes d'agrumes confits mélangés, hachés","1 c. à soupe de farine ordinaire pour étaler","1 c. à café de sucre en poudre"],
["Préchauffez le four à 170 °C (th. 3).","Dans un grand saladier, battez l'huile, l'œuf, le sucre, la stévia, le zeste de citron et le jus de citron.","Ajoutez la farine, les épices, les raisins de Corinthe et les zestes confits et mélangez bien jusqu'à ce que la pâte forme une boule.","Déposez la pâte sur un plan de travail bien fariné et étalez-la sur 3 à 4 mm d'épaisseur.","À l'aide d'un emporte-pièce cannelé de 5 cm, découpez les biscuits et déposez-les délicatement sur une plaque de cuisson légèrement huilée, en réétalant les chutes au fur et à mesure. Vous devriez obtenir environ 25 biscuits.","Faites cuire environ 7 à 9 minutes, jusqu'à ce que les bords commencent juste à dorer, saupoudrez de sucre en poudre et laissez refroidir sur une grille."],
["Vous pouvez utiliser un emporte-pièce en forme de lapin ou de canard pour faire de jolis biscuits de Pâques pour les enfants.","Si vous n'avez pas de raisins de Corinthe, des raisins secs ou des raisins de Smyrne conviennent tout aussi bien, ou utilisez 50 g de fruits secs mélangés à la place des raisins de Corinthe et des zestes confits.",FRZ+"peut être congelé une fois cuit. Congelez en portions emballées individuellement. Décongelez 2 heures, ou au micro-ondes."]),
R(7843879,"Poulet piri-piri","Du poulet mariné au piment et au paprika, à cuire au gril, sur une plaque à griller ou au barbecue. Servez avec un filet de jus de citron vert.","2","220 g",
["2 blancs de poulet sans peau (environ 350 g)","2 c. à café d'huile d'olive","1 à 2 piments rouges, finement hachés","4 gousses d'ail, écrasées","2 c. à café de paprika","jus d'1 citron vert","1 citron vert, pour servir"],
["Coupez les blancs de poulet en 2 à 3 morceaux, selon leur taille, pour obtenir des tranches de 1 cm d'épaisseur.","Mettez les tranches de poulet dans un sac alimentaire et ajoutez l'huile d'olive, les piments, l'ail, le paprika et le jus de citron vert. Mélangez bien pour enrober le poulet. Laissez reposer 15 minutes, ou placez au réfrigérateur et laissez toute la nuit.","Chauffez votre gril, votre barbecue ou votre plaque à griller et ajoutez le poulet. Retournez après 3 minutes et faites cuire encore 3 minutes. Vérifiez qu'il est cuit à cœur, sans aucune chair rose au milieu. Déposez dans une assiette.","Enfin, coupez le citron vert en deux et posez-le, face coupée vers le bas, sur la plaque à griller pendant quelques minutes. Servez avec le poulet."],
["Vous pouvez aussi utiliser cette marinade piri-piri sur des escalopes de dinde ou de porc.","Pour une version végétarienne, faites cuire et laissez refroidir de gros morceaux de légumes comme des carottes, des betteraves, des patates douces, des pommes de terre ou de la courge butternut, et faites-les mariner dans le mélange piri-piri avant de les griller ou de les cuire au barbecue.","Pour congeler, enveloppez dans du papier aluminium ou sulfurisé à l'intérieur de sacs de congélation et étiquetez. Ils se conservent jusqu'à 3 mois.",fv(0)]),
]
save(3,recs)
